recipes.code:
{
  "inputs": [
    {
      "id": "famulor-api-key",
      "type": "promptString",
      "description": "Famulor API key (create at https://app.famulor.de → API Keys)",
      "password": true
    }
  ],
  "servers": {
    "famulor": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "famulor-mcp@0.3.1"
      ],
      "env": {
        "FAMULOR_API_KEY": "${input:famulor-api-key}"
      }
    }
  }
}
